async function scanBundle(input, deliver) {
  let count = 0;

  try {
    const decoder = new TextDecoder("utf-8", { ignoreBOM: true });
    let line = 1;
    let parts = [];

    async function finishLine(bytes) {
      const tail = decoder.decode(bytes);
      if (tail.length > 0) parts.push(tail);

      const text = parts.join("");
      parts = [];

      if (text.trim() === "") return true;

      let value;
      try {
        value = JSON.parse(text);
      } catch {
        const error = new Error("Invalid JSON at line " + line);
        error.code = "BAD_LINE";
        error.line = line;
        throw error;
      }

      count++;
      return (await deliver(value, line)) !== false;
    }

    while (true) {
      const chunk = await input.read();

      if (chunk === null) {
        await finishLine();
        return count;
      }

      let start = 0;

      while (start < chunk.length) {
        const end = chunk.indexOf(0x0a, start);

        if (end === -1) {
          const part = decoder.decode(chunk.subarray(start), {
            stream: true
          });
          if (part.length > 0) parts.push(part);
          break;
        }

        if (!(await finishLine(chunk.subarray(start, end)))) {
          return count;
        }

        line++;
        start = end + 1;
      }
    }
  } finally {
    await input.close();
  }
}
